import{_ as l,a0 as r,w as p,s as a,ao as u,I as i,x as n,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"系統監控中心：一個理想的 Linux 任務管理器和資源監視器 | LCTT x X-CMD","titleTemplate":false,"description":"系統監控中心：一個理想的 Linux 任務管理器和資源監視器 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系統監控中心：一個理想的 Linux 任務管理器和資源監視器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系統監控中心：一個理想的 Linux 任務管理器和資源監視器 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux","title":"系統監控中心：一個理想的 Linux 任務管理器和資源監視器","tag":"202112","desc":""},"relativePath":"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux.md","filePath":"[post].md"}'),m={name:"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux.md"};function d(f,t,g,x,C,L){const e=r("Link");return p(),a("div",null,[t[19]||(t[19]=u('<h1 id="系統監控中心-一個理想的-linux-任務管理器和資源監視器" tabindex="-1">系統監控中心：一個理想的 Linux 任務管理器和資源監視器 <a class="header-anchor" href="#系統監控中心-一個理想的-linux-任務管理器和資源監視器" aria-label="Permalink to “系統監控中心：一個理想的 Linux 任務管理器和資源監視器”">​</a></h1><blockquote><p>“系統監控中心”是一個多合一的開源應用，不用使用多種工具就可以監控基本的系統資源情況。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/10/131211ng09sz76u2b7gbaw.jpg" alt=""></p><p>在 Linux 上以圖形方式監控系統資源可能體驗不是很好，這些與你的桌面環境相配套的系統監控工具可能細節有限。</p><p>例如，GNOME 的系統監視器不顯示 CPU 頻率和温度。</p><p>此外，Linux 的默認系統監控程序通常以簡單為目標，而不是提供詳細的信息。</p><p>“<ruby>系統監控中心<rt>System Monitoring Center</rt></ruby>” 是一個有用的 GUI 工具，它提供了大量必要的信息。在這篇文章中，讓我給你詳細介紹一下它。</p><h3 id="系統監控中心-顯示基本系統統計信息的-linux-應用" tabindex="-1">系統監控中心：顯示基本系統統計信息的 Linux 應用 <a class="header-anchor" href="#系統監控中心-顯示基本系統統計信息的-linux-應用" aria-label="Permalink to “系統監控中心：顯示基本系統統計信息的 Linux 應用”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center.png?resize=800%2C611&amp;ssl=1" alt=""></p><p>系統監控中心是一個基於 GTK3 和 Python 3 的外觀時尚的應用，它為你提供了你想要的所有資源使用數據。</p><p>在我的例子中，我想在使用系統監控工具時關注 CPU 的頻率，但 GNOME 的系統監控工具提供不了幫助。所以，這個應用就非常有用了。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-full-info.png?resize=800%2C585&amp;ssl=1" alt=""></p><p>該應用的用户體驗良好，並提供了大量的信息和功能。讓我重點介紹一下它的主要功能。</p><blockquote><p>寫這篇文章時，該應用程序仍處於測試階段。因此，你可能會遇到一些錯誤。然而，我在簡短的測試中沒有注意到任何問題。</p></blockquote><h3 id="系統監控中心的功能" tabindex="-1">系統監控中心的功能 <a class="header-anchor" href="#系統監控中心的功能" aria-label="Permalink to “系統監控中心的功能”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-options.png?resize=582%2C576&amp;ssl=1" alt=""></p><p>首先，它可以讓你查看 CPU、內存、磁盤、網絡、GPU 和傳感器的單獨統計數據。</p><p>你可以在該工具中看到以下細節信息：</p><ul><li>顯示 CPU 狀態，包括頻率</li><li>能夠顯示平均使用率或每個核心的使用率</li><li>可以選擇 CPU 頻率和其他統計的精度</li><li>能夠改變圖表的顏色</li><li>按用户過濾系統進程並輕鬆管理它們</li><li>切換一個浮動的摘要小部件，以快速獲得信息</li><li>顯示磁盤使用信息和連接的驅動器</li><li>在同一個應用中顯示詳細的系統信息</li><li>控制啓動服務和程序</li><li>能夠控制狀態更新的時間間隔</li><li>應用本身的系統資源使用率較低</li><li>適應系統主題</li></ul><p>雖然它為每個標籤（或組件）提供了大量的選項和自定義功能，但我希望它能在未來的更新中包括 RAM 頻率等東西。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-cpu-monitoring.png?resize=800%2C599&amp;ssl=1" alt=""></p><p>然而，考慮到它可以同時取代磁盤使用分析器和 <code>neofetch</code> 等終端工具，其餘的數據似乎非常有用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-process.png?resize=800%2C592&amp;ssl=1" alt=""></p><p>請注意，如果你有多個機箱風扇、獨立的排風扇或 AIO，你可能無法得到風扇的數據。温度也可能有或沒有，但 CPU 的温度應該是可見的。</p><h3 id="在-linux-中安裝系統監控中心" tabindex="-1">在 Linux 中安裝系統監控中心 <a class="header-anchor" href="#在-linux-中安裝系統監控中心" aria-label="Permalink to “在 Linux 中安裝系統監控中心”">​</a></h3><p>你可以使用可用的 deb 包在任何基於 Ubuntu 的發行版上輕鬆安裝它。</p><p>不幸的是，沒有可用的其他軟件包，只有一個 ZIP 文件，你得手動構建和編譯才能安裝它。你在 ZIP 文件中可以找到一個腳本來構建 RPM 包。</p>',27)),i("p",null,[t[1]||(t[1]=n("deb 文件可以通過 SourceForge 獲得。你點擊下面的按鈕來下載它，或者在他們的 ",-1)),s(e,{href:"https://kod.pardus.org.tr/Hakan/system-monitoring-center"},{default:o(()=>[...t[0]||(t[0]=[n("GitLab 頁面",-1)])]),_:1}),t[2]||(t[2]=n(" 找到。",-1))]),i("ul",null,[i("li",null,[s(e,{href:"https://sourceforge.net/projects/system-monitoring-center/files/latest/download"},{default:o(()=>[...t[3]||(t[3]=[n("下載系統監控中心",-1)])]),_:1})])]),t[20]||(t[20]=i("h3",{id:"總結",tabindex:"-1"},[n("總結 "),i("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[21]||(t[21]=i("p",null,"系統監控中心是一個開源應用，可以讓用户詳細瞭解他們的系統資源，並幫助管理進程。",-1)),t[22]||(t[22]=i("p",null,"對於許多 Linux 用户來説，這是一個非常需要的應用，不需要使用單獨的終端/GUI 程序就可以提供詳細的信息。",-1)),t[23]||(t[23]=i("hr",null,null,-1)),i("p",null,[t[5]||(t[5]=n("via: ",-1)),s(e,{href:"https://itsfoss.com/system-monitoring-center/"},{default:o(()=>[...t[4]||(t[4]=[n("https://itsfoss.com/system-monitoring-center/",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=n("作者：",-1)),s(e,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...t[6]||(t[6]=[n("Ankush Das",-1)])]),_:1}),t[11]||(t[11]=n(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[7]||(t[7]=[n("lujun9972",-1)])]),_:1}),t[12]||(t[12]=n(" 譯者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[8]||(t[8]=[n("geekpi",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=n("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const M=l(m,[["render",d]]);export{k as __pageData,M as default};
